/* ═══════════════ Run flow: Visualize execution + trace handback ═══════════════ */

import { state } from './state.js';
import { els } from './dom.js';
import { syncVisualizeEnabled, applyLock } from './lock.js';
import { render } from './panels/output.js';
import { scanStackSource } from './panels/stack.js';
import { cancelStepGlide, scrollToLine } from './navigation/steps.js';

// Back to the pre-run state: arrows, highlights, output, variables, step
// counter, and slider all reset (the trace is regenerated by Visualize).
export function resetRun() {
  cancelStepGlide();
  state.steps = [];
  state.programError = null;
  state.stoppedRun = false;
  state.idx = 0;
  state.programOutput = '';
  state.outTab = 'out'; state.userTab = false;
  state.treeAnnounced = false; state.stackAnnounced = false;
  state.reverseAnnounced = false;
  state.palindromeAnnounced = false;
  state.stackScan = null;
  render();
}

els.visualize.addEventListener('click', async () => {
  const code = els.textarea.value;
  if (!code.trim()) {
    // Nothing to visualize (the button is disabled for this, but guard the
    // race where the editor was cleared mid-click): clear the stale panels.
    resetRun();
    return;
  }
  resetRun();
  // Stack detection pinned to the exact code being executed (see
  // 2026-11-03-stack-visualiser-design.md).
  state.stackScan = scanStackSource(code);
  state.runInProgress = true;
  state.locked = true;
  syncVisualizeEnabled();
  applyLock();
  els.status.textContent = 'Executing…';
  els.status.classList.remove('ready');
  let failed = false;
  try {
    state.pyodide.globals.set('__viz_code', code);
    const json = await state.pyodide.runPythonAsync('__viz_run(__viz_code)');
    const result = JSON.parse(json);

    // The editor was emptied while the run was in flight: discard the result.
    if (!els.textarea.value.trim()) { resetRun(); return; }

    state.programOutput = result.output || '';
    state.steps = result.steps || [];
    state.stoppedRun = !!result.stopped;

    if (result.error) {
      failed = true;
      state.programError = { text: result.error, line: result.errorLine };
      if (!result.errorLine || !state.steps.length) {
        // A syntax error before anything ran: no stepping is possible.
        state.steps = [];
      }
    }
    if (state.stoppedRun) failed = true;
    if (!state.steps.length) {
      render();
      scrollToLine(state.programError && state.programError.line);
      return;
    }
    // An error or a limit stop lands straight on the last executed line —
    // the buggy line for runtime errors — instead of the first step.
    if (state.programError || state.stoppedRun) {
      // Terminal state: the editor is already auto-unlocked via the failed
      // flag, and navigation stays live just like the successful final step —
      // users can trace back to (or revisit) any recorded step; the first
      // real edit resets the run.
      state.idx = state.steps.length - 1;
      render();
      scrollToLine(state.steps[state.idx].line);
      return;
    }
    // Successful run: land on the final step so the output is visible.
    state.idx = state.steps.length - 1;
    render();
    scrollToLine(state.steps[state.idx].line);
  } catch (err) {
    failed = true;
    state.programError = { text: 'Internal error: ' + (err && err.message || err), line: null };
    state.steps = [];
    render();
  } finally {
    state.runInProgress = false;
    // Both failed and successful runs unlock the editor so the Edit button
    // is enabled. The trace stays navigable (playback controls live) until
    // the user actually starts editing — the input listener then resets.
    state.locked = false;
    syncVisualizeEnabled();
    applyLock();
    els.status.textContent = 'Python ready ✓';
    els.status.classList.add('ready');
  }
});
